import{_ as e,c as i,o as a,ag as t}from"./chunks/framework.DCv_I274.js";const k=JSON.parse('{"title":"Security basics","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/security-basics.md","filePath":"fundamentals/security-basics.md","lastUpdated":null}'),n={name:"fundamentals/security-basics.md"};function l(r,s,o,h,d,p){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="security-basics" tabindex="-1">Security basics <a class="header-anchor" href="#security-basics" aria-label="Permalink to &quot;Security basics&quot;">​</a></h1><p>The mistakes below cause most real-world breaches. Laravel protects you from many of them <strong>if you use it the intended way</strong>.</p><h2 id="_1-injection-sql-injection" tabindex="-1">1. Injection (SQL injection) <a class="header-anchor" href="#_1-injection-sql-injection" aria-label="Permalink to &quot;1. Injection (SQL injection)&quot;">​</a></h2><p>Building SQL from user input lets an attacker rewrite the query:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ NEVER</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// $email = &quot;&#39; OR &#39;1&#39;=&#39;1&quot; returns every user</span></span></code></pre></div><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅ Eloquent / query builder / bindings escape values for you</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">User</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;email&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $email)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">first</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ?&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [$email]);</span></span></code></pre></div><p>Also never pass user input as a <strong>column name</strong> (<code>orderBy($request-&gt;sort)</code>); use an allow-list. <a href="/foundations/05-query-traits">Query traits</a> do this with <code>implementSort()</code>.</p><h2 id="_2-broken-authentication" tabindex="-1">2. Broken authentication <a class="header-anchor" href="#_2-broken-authentication" aria-label="Permalink to &quot;2. Broken authentication&quot;">​</a></h2><ul><li>Hash passwords with <code>Hash::make()</code> (bcrypt/argon). Never store or log plain passwords.</li><li>Give the <strong>same error</strong> for &quot;no such account&quot; and &quot;wrong password&quot;, so attackers can&#39;t discover which emails exist.</li><li>Rate-limit login (<code>throttle</code> middleware).</li><li>Keep access tokens short-lived. Store long-lived refresh tokens in an <strong>httpOnly</strong> cookie and only as a <strong>hash</strong> on the server. <a href="/foundations/09-refresh-sessions">Refresh sessions</a> does all of this.</li></ul><h2 id="_3-broken-access-control" tabindex="-1">3. Broken access control <a class="header-anchor" href="#_3-broken-access-control" aria-label="Permalink to &quot;3. Broken access control&quot;">​</a></h2><p>Logged in does not mean allowed.</p><ul><li>Every route declares its permission (<a href="/foundations/10-rbac">RBAC</a>).</li><li><strong>IDOR</strong> (insecure direct object reference): <code>GET /api/v1/files/57</code> must check that the user may see file 57, not just that the id exists. Scope queries to the user (<code>where(&#39;user_id&#39;, $user-&gt;id)</code>) or check ownership.</li><li>Never trust ids or roles sent by the client (<code>user_role_id</code> in a profile update). Validate them, and only accept fields the user may change (<code>$fillable</code> + FormRequest).</li></ul><h2 id="_4-cross-site-scripting-xss" tabindex="-1">4. Cross-site scripting (XSS) <a class="header-anchor" href="#_4-cross-site-scripting-xss" aria-label="Permalink to &quot;4. Cross-site scripting (XSS)&quot;">​</a></h2><p>An attacker stores JavaScript (for example in a name field) that later runs in other users&#39; browsers.</p><div><ul><li>Blade <code>{{ $value }}</code> <strong>escapes</strong> output. Use <code>{!! $value !!}</code> only for HTML you created yourself.</li><li>In Vue/React, avoid <code>v-html</code> / <code>dangerouslySetInnerHTML</code> with user data.</li><li>Keep tokens out of <code>localStorage</code> when you can: an XSS bug can read it, but not an httpOnly cookie.</li></ul></div><h2 id="_5-cross-site-request-forgery-csrf" tabindex="-1">5. Cross-site request forgery (CSRF) <a class="header-anchor" href="#_5-cross-site-request-forgery-csrf" aria-label="Permalink to &quot;5. Cross-site request forgery (CSRF)&quot;">​</a></h2><p>Another website makes the victim&#39;s browser send a request <strong>with the victim&#39;s cookies</strong>.</p><ul><li>Blade forms: <code>@csrf</code> adds a token that other sites can&#39;t know.</li><li>Cookie-authenticated API endpoints: check the <code>Origin</code> header and use <code>SameSite</code> cookies (<a href="/foundations/09-refresh-sessions">Refresh sessions</a>).</li><li><code>Authorization: Bearer</code> requests are not affected: browsers never add that header by themselves.</li></ul><h2 id="_6-sensitive-data-exposure" tabindex="-1">6. Sensitive data exposure <a class="header-anchor" href="#_6-sensitive-data-exposure" aria-label="Permalink to &quot;6. Sensitive data exposure&quot;">​</a></h2><ul><li>HTTPS everywhere in production.</li><li>Return only the fields the client needs, through <strong>API resources</strong>. Never return raw models (they may include hashes or internal columns).</li><li><code>APP_DEBUG=false</code> in production. Debug pages show your environment variables.</li><li>Secrets live in <code>.env</code>, never in Git. Rotate any secret that was committed.</li></ul><h2 id="_7-mass-assignment" tabindex="-1">7. Mass assignment <a class="header-anchor" href="#_7-mass-assignment" aria-label="Permalink to &quot;7. Mass assignment&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ the client could send &quot;user_role_id&quot;: 1 and become an administrator</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($request</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅ only validated fields, and only fields listed in $fillable</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($request</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">validated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><h2 id="_8-file-uploads" tabindex="-1">8. File uploads <a class="header-anchor" href="#_8-file-uploads" aria-label="Permalink to &quot;8. File uploads&quot;">​</a></h2><ul><li>Validate type and size (<code>mimes:pdf,jpg|max:2048</code>).</li><li>Store outside <code>public/</code> (the <strong>private</strong> disk) under a generated name.</li><li>Serve through a controller or a <strong>signed, expiring URL</strong> (<a href="/foundations/12-file-uploads">File uploads</a>).</li></ul><h2 id="_9-logging-and-monitoring" tabindex="-1">9. Logging and monitoring <a class="header-anchor" href="#_9-logging-and-monitoring" aria-label="Permalink to &quot;9. Logging and monitoring&quot;">​</a></h2><ul><li>Log security events (logins, logouts, refresh-token reuse, permission changes) to the activity log.</li><li>Never log secrets: passwords, tokens, peppers, full card numbers.</li></ul><h2 id="_10-dependencies" tabindex="-1">10. Dependencies <a class="header-anchor" href="#_10-dependencies" aria-label="Permalink to &quot;10. Dependencies&quot;">​</a></h2><p>Run <code>composer audit</code> and <code>npm audit</code> regularly and update vulnerable packages.</p><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul><li>[ ] Every query uses Eloquent/bindings; sort columns come from an allow-list</li><li>[ ] Every route has authentication <strong>and</strong> a permission check</li><li>[ ] Records are scoped to what the user may see</li><li>[ ] Output goes through resources; <code>APP_DEBUG=false</code> in production</li><li>[ ] Controllers only use <code>$request-&gt;validated()</code></li><li>[ ] Login is rate-limited and doesn&#39;t reveal which accounts exist</li><li>[ ] Uploads are validated, private, and served through a controller or a signed URL</li><li>[ ] No secrets in Git or logs</li></ul><p>Next: <a href="/start/prerequisites">Prerequisites</a></p>`,31)])])}const u=e(n,[["render",l]]);export{k as __pageData,u as default};
